type Screen interface {
	tea.Model
	Render() string
}

// setView is the one door into a.views. It panics, naming the view, when the
// model has no Render(): a view that cannot be drawn is a programming error to
// catch at the install site, not a blank screen later.
func (a *App) setView(vt command.ViewType, m tea.Model) {
	screen, ok := m.(Screen)
	if !ok {
		panic(fmt.Sprintf("app: view %q (%T) has no Render() string, it is not a Screen", vt, m))
	}
	a.views[vt] = screen
}

// FormView interface for views that can have active forms
// Views implementing this interface can prevent command mode activation
type FormView interface {
	InEditMode() bool
}
}

// BlinkingView is implemented by a view with a row that blinks for a reason the
// registry does not know (an instant action, an agent running, children loading).
// The router asks the view on screen after every Update: a level, not an edge.
type BlinkingView interface {
	WantsBlink() bool
}

// Update is the router's only entry: the dispatch, then the level check of the
// animation chain. The view's own Cmd goes through untouched; ensureTick adds a
// Cmd only when a chain has to start or be replaced, and is idempotent, so a
// handler that already called it (jobsChanged) does not double the interval.
func (a *App) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	if _, ok := msg.(tea.FocusMsg); ok && !a.terminalBlurred {
		return a, nil // focus with no prior blur: nothing to do (DEVDESK-210)
	}
	model, cmd := a.update(msg)
	return model, tea.Batch(cmd, a.ensureTick())
}

// wantsBlink reports whether the view on screen has a row that blinks.
func (a *App) wantsBlink() bool {
	view, ok := a.views[a.currentView].(BlinkingView)
	return ok && view.WantsBlink()
}

// applyMotion points the animation at the motion a config asks for. It is
// called wherever the router takes a new config (context switch, every save);
// the constructor sets the field directly because it has no Cmd to return.
func (a *App) applyMotion(cfg *config.Config) tea.Cmd {
	return a.setMotionStatic(cfg.App.StaticMotion())
}

// setMotionStatic pins the blink phase on and stops blink-only chains. The view
// on screen is handed the pinned frame at once, otherwise it would keep an off
// phase until the next tick that may never come.
func (a *App) setMotionStatic(on bool) tea.Cmd {
	a.motionStatic = on
	if !on {
		return nil
	}
	a.anim.blinkOn = true
	return a.sendFrameTo(a.currentView)
}

func (a *App) update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		a.resize(msg.Width, msg.Height)
		return a, nil

	case tea.ColorProfileMsg:
		// Router state only (View sets the terminal background); not forwarded.
		a.colorProfile = msg.Profile
		return a, nil

	case tea.BlurMsg:
		return a.handleTerminalBlur()

	case tea.FocusMsg:
		return a.handleTerminalFocus()

	case tea.KeyPressMsg:
		_, focusCmd := a.handleTerminalFocus() // input proves the terminal has the focus
		model, keyCmd := a.handleKeyMsg(msg)
		return model, tea.Batch(focusCmd, keyCmd)

	case tea.PasteMsg:
		a.handleTerminalFocus()
		return a.handlePasteMsg(msg)

	// ── Contexts and themes ──────────────────────────────────────────────
	case configuration.ConfigSavedMsg:
		return a.handleConfigSaved(msg)

	case contextNamesLoadedMsg:
		return a.handleContextNamesLoaded(msg)

	case MCPServerStartedMsg:
		return a.handleMCPServerStarted(msg)

	case mcpJobsRequestMsg:
		return a.handleMCPJobsRequest(msg)

	case mcpForwardsRequestMsg:
		return a.handleMCPForwardsRequest(msg)

	case mcpStartRequestMsg:
		return a.handleMCPStartRequest(msg)

	case mcpCancelRequestMsg:
		return a.handleMCPCancelRequest(msg)

	case jobs.RefusedMsg:
//
// It is not selection.go, on purpose. That file translates each borrower's
// request into its own vocabulary, because what the explorer borrows is two
// different views answering two different questions. Here the question is
// always "which path", so one message pair serves every borrower and Tag says
// which field it was for. The return slot is its own for the same reason the
// pair is: the templates view can itself be lent to the explorer, and a picker
// opened from its form must not overwrite where that borrow returns to.

// handlePickRequest lends a picker, remembering who asked.
func (a *App) handlePickRequest(msg filebrowser.PickRequestMsg) (tea.Model, tea.Cmd) {
	a.pickerReturnView = a.currentView
	log.Printf("Path picker requested by %s (tag %q)", a.currentView, msg.Tag)
	picker := filebrowser.NewPicker(a.config, msg)
	a.setView(command.ViewFiles, picker)
	a.currentView = command.ViewFiles
	return a, tea.Batch(picker.Init(), a.requestResize(), a.enterView(command.ViewFiles))
}

// handlePickAnswer returns to the borrower with its answer — chosen or not —
// and drops the lent picker, so `:files` next time is the browser, not it.
func (a *App) handlePickAnswer(msg tea.Msg) (tea.Model, tea.Cmd) {
	delete(a.views, command.ViewFiles)
	a.currentView = a.pickerReturnView
	a.pickerReturnView = ""
	return a, a.returnToOrigin(msg)
