// handleViewerOpenRequest opens a document, wherever the request came from.
//
// The router does no I/O here, and that is the difference from
// handleWorkspaceScanDetails: a scan result is a cache file the router owns,
// while a file on disk and a `docker inspect` belong to their producers. The
// message carries a source, the viewer loads it in its own Init, and one place
// therefore decides what is too large or not text — and reports it.
func (a *App) handleViewerOpenRequest(msg uiviewer.OpenRequestMsg) (tea.Model, tea.Cmd) {
	if msg.Source == nil {
		return a, nil
	}

	view := uiviewer.NewWithSource(a.config, msg.Source)
	// Where esc goes back to is read from the router rather than carried on the
	// message: the view the user is looking at *is* the one that asked, and a
	// producer naming itself would be a second copy of that fact.
	view.OriginView = a.currentView

	a.setView(command.ViewViewer, view)
	a.currentView = command.ViewViewer
	return a, tea.Batch(view.Init(), a.requestResize())
}
// handleNetdiagOpenRequest opens netdiag prefilled with a target named by
// whoever asked — today, a monitor selected in status (§3.66, keymap.Diagnose).
//
// It mirrors handleViewerOpenRequest: the producer names only what it knows
// (the target, and whether the port is certain enough to run immediately),
// the router builds the view and remembers where esc should return to.
func (a *App) handleNetdiagOpenRequest(msg netdiag.OpenRequestMsg) (tea.Model, tea.Cmd) {
	view := netdiag.NewWithTarget(a.config, msg.Target)
	view.OriginView = a.currentView

	a.setView(command.ViewNetdiag, view)
	a.currentView = command.ViewNetdiag

	cmds := []tea.Cmd{view.Init(), a.requestResize()}
	if msg.AutoRun {
		var cmd tea.Cmd
		_, cmd = view.StartRun()
		cmds = append(cmds, cmd)
	}
	return a, tea.Batch(cmds...)
}
	// Reset GitLab auth state — the new context has its own credentials
	a.clearAuthenticated()

	// Apply auto-login result from the context switch if successful
	var indexCmd tea.Cmd
	if msg.Forge != nil {
		indexCmd = a.setAuthenticated(msg.Forge, msg.GitLabUser)
	} else {
		// No credentials available — navigate to auth view for manual login
		a.currentView = command.ViewGitAuth
	}

	// The new context's tools may run from elsewhere: its views start from
	// "not known yet" rather than from the previous context's answer.
	a.forgetScanTools()


// handleTemplateSelectionCancelled returns to the explorer without a choice.
func (a *App) handleTemplateSelectionCancelled() (tea.Model, tea.Cmd) {
	a.leaveSelectionMode()
	return a, a.returnToOrigin(explorer.TemplateChoiceCancelledMsg{})
}

